<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'Resi' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-primary transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 truncate font-medium text-ui-ink-gray-900">Tambah Resi</span>
			</div>
		</div>

		<!-- ============ FORM ============ -->
		<div class="flex flex-1 flex-col">
			<div class="app-container-narrow px-4 py-5 text-base md:px-6">
				<pre
					v-if="saveError"
					class="mb-4 rounded-md border border-ui-line-red-200 bg-ui-surface-red-50 px-3 py-2 text-sm text-ui-ink-red-700 whitespace-pre-wrap"
					>{{ saveError }}</pre
				>

				<section
					class="space-y-4 rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
				>
					<!-- Sumber menentukan master nasabah; harus dipilih lebih dulu.
					     Dua pilihan saja, jadi ditampilkan berdampingan, bukan
					     dropdown: keduanya langsung terbaca dan cukup sekali ketuk. -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
							Sumber <span class="text-ui-ink-red-500">*</span>
						</label>
						<div class="grid grid-cols-2 gap-2">
							<button
								v-for="o in SUMBER_OPTIONS"
								:key="o"
								type="button"
								class="min-h-[44px] rounded-xl border px-3 py-2 text-sm font-semibold transition active:scale-[0.99]"
								:class="
									form.sumber === o
										? 'border-primary bg-primary/5 text-primary'
										: 'border-ui-line-gray-300 text-ui-ink-gray-600'
								"
								@click="pilihSumber(o)"
							>
								{{ o }}
							</button>
						</div>
					</div>

					<!-- No Perjanjian (master sesuai sumber, searchable) -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
							No Perjanjian <span class="text-ui-ink-red-500">*</span>
						</label>
						<div class="relative">
							<input
								v-model="nasabahQuery"
								type="text"
								:placeholder="
									form.sumber
										? 'Cari No Perjanjian / nama nasabah…'
										: 'Pilih Sumber terlebih dahulu'
								"
								:disabled="!form.sumber"
								:class="[inputClass, !form.sumber && 'opacity-60']"
								@focus="onNasabahFocus"
								@input="onNasabahSearch"
							/>
							<div
								v-if="nasabahOpen"
								class="absolute z-30 mt-1 max-h-56 w-full overflow-y-auto rounded-xl border border-ui-line-gray-200 bg-ui-surface shadow-lg"
							>
								<p v-if="nasabahSearching" class="px-3 py-2 text-xs text-ui-ink-gray-400">
									Mencari…
								</p>
								<p
									v-else-if="!nasabahResults.length"
									class="px-3 py-2 text-xs text-ui-ink-gray-400"
								>
									Tidak ada data.
								</p>
								<button
									v-for="r in nasabahResults"
									:key="r.name"
									type="button"
									class="block w-full px-3 py-2 text-left text-xs hover:bg-primary/5"
									@click="selectNasabah(r)"
								>
									<span class="font-semibold text-ui-ink-gray-800">{{
										r.nama_nasabah || r.name
									}}</span>
									<span class="block truncate text-ui-ink-gray-400">{{ r.name }}</span>
								</button>
							</div>
						</div>
						<div
							v-if="nasabahOpen"
							class="fixed inset-0 z-20"
							@click="nasabahOpen = false"
						/>
					</div>

					<!-- Data nasabah terpilih (read-only, cermin fetch_from doctype) -->
					<div
						v-if="form.no_perjanjian"
						class="space-y-1.5 rounded-xl bg-ui-surface-gray-50 px-3 py-2.5 text-xs"
					>
						<p v-if="previewLoading" class="text-center text-ui-ink-gray-400">
							Memuat data nasabah…
						</p>
						<template v-else>
							<div
								v-for="p in previewRows"
								:key="p.label"
								class="flex items-start justify-between gap-3"
							>
								<span class="shrink-0 text-ui-ink-gray-500">{{ p.label }}</span>
								<span
									class="min-w-0 break-words text-right font-medium text-ui-ink-gray-800"
									>{{ p.value }}</span
								>
							</div>
						</template>
					</div>

					<!-- Upload Bukti Transfer -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
							Bukti Transfer <span class="text-ui-ink-red-500">*</span>
						</label>

						<!-- Pratinjau gambar -->
						<div
							v-if="form.gambar_resi"
							class="relative mb-2 overflow-hidden rounded-xl border border-ui-line-gray-200 bg-ui-surface-gray-50"
						>
							<img
								:src="form.gambar_resi"
								alt="Pratinjau bukti transfer"
								class="mx-auto max-h-[420px] w-auto max-w-full object-contain"
							/>
							<button
								type="button"
								class="absolute right-2 top-2 flex h-8 w-8 items-center justify-center rounded-full bg-black/50 text-white transition hover:bg-black/70"
								aria-label="Hapus gambar"
								@click="form.gambar_resi = ''"
							>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="h-4 w-4"
									fill="none"
									stroke="currentColor"
									stroke-width="2"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<path d="M18 6 6 18" />
									<path d="m6 6 12 12" />
								</svg>
							</button>
						</div>

						<div class="flex gap-2">
							<button
								type="button"
								:disabled="uploading"
								class="flex flex-1 items-center justify-center gap-2 rounded-md border border-dashed border-ui-line-gray-300 px-3 py-3 text-sm text-ui-ink-gray-500 transition hover:border-primary disabled:opacity-50"
								@click="pickFile"
							>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="h-5 w-5 shrink-0"
									fill="none"
									stroke="currentColor"
									stroke-width="1.8"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
									<path d="M17 8l-5-5-5 5" />
									<path d="M12 3v12" />
								</svg>
								{{
									uploading
										? 'Mengunggah…'
										: form.gambar_resi
										? 'Ganti gambar'
										: 'Pilih gambar'
								}}
							</button>
							<button
								v-if="showCamera"
								type="button"
								:disabled="uploading"
								class="flex shrink-0 items-center justify-center gap-2 rounded-md border border-ui-line-gray-300 px-4 py-3 text-sm font-medium text-ui-ink-gray-700 transition hover:border-primary disabled:opacity-50"
								@click="takePhoto"
							>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="h-5 w-5 shrink-0"
									fill="none"
									stroke="currentColor"
									stroke-width="1.8"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<path
										d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"
									/>
									<circle cx="12" cy="13" r="3" />
								</svg>
								Kamera
							</button>
						</div>
						<p class="mt-1 text-xs text-ui-ink-gray-400">Format JPG/PNG, maks 5 MB.</p>
						<input
							ref="fileInput"
							type="file"
							class="hidden"
							accept="image/*"
							@change="onFileChange"
						/>
					</div>
				</section>

				<p class="mt-3 px-1 text-xs text-ui-ink-gray-400">
					Setelah disimpan, gambar langsung diekstraksi otomatis. Mohon tunggu di halaman
					ini sampai hasil muncul.
				</p>
			</div>
		</div>

		<!-- ============ ACTION BAR ============ -->
		<div
			class="sticky bottom-0 z-20 flex gap-2 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3 md:px-6 bottom-bar"
			style="padding-bottom: calc(0.75rem + env(safe-area-inset-bottom))"
		>
			<RouterLink
				:to="{ name: 'Resi' }"
				class="flex flex-1 items-center justify-center rounded-lg border border-ui-line-gray-300 bg-ui-surface py-2.5 text-sm font-medium text-ui-ink-gray-700"
			>
				Batal
			</RouterLink>
			<button
				type="button"
				:disabled="saving || uploading"
				class="flex flex-1 items-center justify-center rounded-lg bg-primary py-2.5 text-sm font-medium text-ui-onPrimary transition hover:opacity-90 disabled:opacity-50"
				@click="submit"
			>
				{{ saving ? 'Menyimpan…' : 'Simpan & Ekstrak' }}
			</button>
		</div>

		<!-- ====== Overlay freeze saat ekstraksi ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-150"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="extracting"
					class="fixed inset-0 z-[100] flex flex-col items-center justify-center gap-4 bg-black/60 px-8 text-center"
				>
					<svg
						class="h-10 w-10 animate-spin text-white"
						xmlns="http://www.w3.org/2000/svg"
						fill="none"
						viewBox="0 0 24 24"
					>
						<circle
							class="opacity-25"
							cx="12"
							cy="12"
							r="10"
							stroke="currentColor"
							stroke-width="4"
						/>
						<path
							class="opacity-75"
							fill="currentColor"
							d="M4 12a8 8 0 0 1 8-8V0C5.4 0 0 5.4 0 12h4z"
						/>
					</svg>
					<p class="text-sm font-medium text-white">
						Mengekstrak data resi… mohon tunggu
					</p>
				</div>
			</Transition>
		</Teleport>

		<!-- Hasil bacaan resi; dialog yang sama dipakai form Aktivitas. -->
		<ResiHasilDialog :isi="hasilResi" @close="tutupHasilResi" />
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { notifyError } from '../composables/toast'
import ResiHasilDialog from '../components/ResiHasilDialog.vue'
import { popupHasilResi } from '../data/resiHasil'
import { canUseCamera, capturePhoto } from '../composables/cameraCapture'

const router = useRouter()

// Hasil bacaan ditampilkan sebagai dialog sebelum berpindah ke detail.
const hasilResi = ref(null)
const tujuanSetelahHasil = ref('')
function tutupHasilResi() {
	const name = tujuanSetelahHasil.value
	hasilResi.value = null
	tujuanSetelahHasil.value = ''
	if (name) router.push({ name: 'ResiDetail', params: { name } })
}
const DOCTYPE = 'Resi'
const MAX_MB = 5

const form = reactive({
	sumber: '',
	no_perjanjian: '',
	gambar_resi: '',
})

// Master nasabah & label rekening berbeda per sumber: JG tidak punya kolom
// no_rekening_tabungan, yang setara di sana adalah nomor BRIVA.
const SUMBER_OPTIONS = ['KSP', 'JG']
const NASABAH_DOCTYPE = {
	KSP: 'Master Data Nasabah',
	JG: 'Master Data Nasabah JG',
}
const nasabahDoctype = computed(() => NASABAH_DOCTYPE[form.sumber] || '')
const saving = ref(false)
const extracting = ref(false)
const saveError = ref('')

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

const showCamera = canUseCamera()

// ---- Pemilih No Perjanjian (Master Data Nasabah) --------------------------
const nasabahQuery = ref('')
const nasabahOpen = ref(false)
const nasabahSearching = ref(false)
const nasabahResults = ref([])
let nasabahTimer = null

// Ganti sumber berarti ganti master nasabah: kontrak yang terlanjur dipilih
// milik master lama, jadi dikosongkan supaya tidak tersimpan silang.
function pilihSumber(value) {
	if (form.sumber === value) return
	form.sumber = value
	onSumberChange()
}

function onSumberChange() {
	form.no_perjanjian = ''
	nasabahQuery.value = ''
	nasabahResults.value = []
	nasabahOpen.value = false
	preview.nama_nasabah = ''
	preview.no_rekening_tabungan = ''
	preview.angsuran = null
	saveError.value = ''
}

function onNasabahFocus() {
	nasabahOpen.value = true
	if (!nasabahResults.value.length) fetchNasabah('')
}
function onNasabahSearch() {
	nasabahOpen.value = true
	clearTimeout(nasabahTimer)
	nasabahTimer = setTimeout(() => fetchNasabah(nasabahQuery.value), 300)
}
async function fetchNasabah(q) {
	if (!nasabahDoctype.value) return
	nasabahSearching.value = true
	try {
		const params = new URLSearchParams({
			doctype: nasabahDoctype.value,
			fields: JSON.stringify(['name', 'nama_nasabah']),
			order_by: 'modified desc',
			limit_page_length: '20',
		})
		const t = (q || '').trim()
		if (t)
			params.set(
				'or_filters',
				JSON.stringify([
					['name', 'like', `%${t}%`],
					['nama_nasabah', 'like', `%${t}%`],
				])
			)
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		nasabahResults.value = json.message || []
	} catch (e) {
		nasabahResults.value = []
	} finally {
		nasabahSearching.value = false
	}
}

// ---- Preview nasabah terpilih (no rekening & angsuran) --------------------
const preview = reactive({
	nama_nasabah: '',
	no_rekening_tabungan: '',
	angsuran: null,
})
const previewLoading = ref(false)
const previewRows = computed(() => [
	{ label: 'Nama Nasabah', value: preview.nama_nasabah || '—' },
	...(form.sumber === 'KSP'
		? [{ label: 'No Rekening Tabungan', value: preview.no_rekening_tabungan || '—' }]
		: []),
	{ label: 'Angsuran', value: preview.angsuran != null ? formatRupiah(preview.angsuran) : '—' },
])
async function selectNasabah(r) {
	form.no_perjanjian = r.name
	nasabahQuery.value = r.nama_nasabah || r.name
	nasabahOpen.value = false
	saveError.value = ''
	previewLoading.value = true
	preview.nama_nasabah = ''
	preview.no_rekening_tabungan = ''
	preview.angsuran = null
	try {
		const params = new URLSearchParams({
			doctype: nasabahDoctype.value,
			filters: r.name,
			fieldname: JSON.stringify(
				form.sumber === 'KSP'
					? ['nama_nasabah', 'no_rekening_tabungan', 'angsuran']
					: ['nama_nasabah', 'angsuran'],
			),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const mdn = (await res.json())?.message || {}
		preview.nama_nasabah = mdn.nama_nasabah || r.nama_nasabah || ''
		preview.no_rekening_tabungan = mdn.no_rekening_tabungan || ''
		preview.angsuran = mdn.angsuran ?? null
	} catch (e) {
		/* preview gagal → biarkan '—'; server tetap isi via fetch_from saat insert */
	} finally {
		previewLoading.value = false
	}
}

// ---- Upload gambar --------------------------------------------------------
const fileInput = ref(null)
const uploading = ref(false)
function pickFile() {
	saveError.value = ''
	if (fileInput.value) {
		fileInput.value.value = ''
		fileInput.value.click()
	}
}
async function onFileChange(e) {
	const file = e.target.files?.[0]
	if (file) await uploadFile(file)
}
async function takePhoto() {
	saveError.value = ''
	const file = await capturePhoto()
	if (file) await uploadFile(file)
}
async function uploadFile(file) {
	if (file.size > MAX_MB * 1024 * 1024) {
		saveError.value = `Ukuran gambar maksimal ${MAX_MB} MB.`
		return
	}
	uploading.value = true
	try {
		const fd = new FormData()
		fd.append('file', file, file.name || 'bukti-transfer.jpg')
		fd.append('upload_doctype', 'Resi')
		fd.append('is_private', '1')
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
		form.gambar_resi = json.message?.file_url || ''
	} catch (err) {
		saveError.value = err.message || String(err)
	} finally {
		uploading.value = false
	}
}

// ---- Util -----------------------------------------------------------------
function formatRupiah(v) {
	const n = Number(v || 0)
	return 'Rp ' + n.toLocaleString('id-ID')
}
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

// ---- Simpan + ekstraksi ----------------------------------------------------
function validate() {
	const missing = []
	if (!form.sumber) missing.push('Sumber')
	if (!form.no_perjanjian) missing.push('No Perjanjian')
	if (!form.gambar_resi) missing.push('Bukti Transfer')
	return missing
}

async function submit() {
	saveError.value = ''
	const missing = validate()
	if (missing.length) {
		saveError.value = `Lengkapi: ${missing.join(', ')}`
		notifyError(saveError.value, 'Data belum lengkap')
		window.scrollTo({ top: 0, behavior: 'smooth' })
		return
	}
	saving.value = true
	try {
		await refreshCsrfToken()
		// Satu endpoint mengerjakan pembuatan dokumen DAN ekstraksinya, memakai
		// jalur yang sama dengan Upload Resi di form aktivitas. Dengan begitu
		// percobaan ulang setelah bukti ditolak MENIMPA dokumen yang gagal itu,
		// bukan menambah Resi baru tiap kali.
		saving.value = false
		extracting.value = true
		const res = await fetch(
			'/api/method/juragan.api.portal.resi.buat_resi',
			{
				method: 'POST',
				credentials: 'include',
				headers: {
					'Content-Type': 'application/json',
					Accept: 'application/json',
					'X-Frappe-CSRF-Token': window.csrf_token || '',
				},
				body: JSON.stringify({
					sumber: form.sumber,
					no_perjanjian: form.no_perjanjian,
					gambar_resi: form.gambar_resi,
				}),
			}
		)
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)

		const hasil = json.message || {}
		const name = hasil.name
		if (!name) throw new Error('Gagal membuat dokumen Resi.')

		// Duplikat & penerima tidak sesuai kontrak tetap berakhir dengan respons
		// sukses — pemberitahuannya hanya ada di ringkasan hasil ini. Detail
		// dibuka setelah dialognya ditutup supaya pesannya benar-benar terbaca.
		hasilResi.value = popupHasilResi(hasil)
		tujuanSetelahHasil.value = name
	} catch (e) {
		saveError.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
		window.scrollTo({ top: 0, behavior: 'smooth' })
	} finally {
		saving.value = false
		extracting.value = false
	}
}

onMounted(async () => {
	await refreshCsrfToken()
})
</script>
